-- Reuse each published media JSON projection inside the existing PDF admission check.

-- No data, limits, permissions, attachment links or other triggers change.

DROP TRIGGER IF EXISTS lesson_media_accepted_pdf_limit_insert;

CREATE TRIGGER lesson_media_accepted_pdf_limit_insert BEFORE INSERT ON setup_head_state
 WHEN EXISTS(WITH parents AS MATERIALIZED (SELECT json_extract(row.value,'$.lesson_id') id,json_extract(row.value,'$.activity_key') activity_key,json_extract(row.value,'$.session_key') session_key FROM setup_head_components h JOIN setup_components c USING(component_id),json_each(c.rows_json) row WHERE h.head_id=NEW.head_id AND h.table_name='lesson_media_lessons' AND json_extract(row.value,'$.state')='PUBLISHED' AND coalesce(json_extract(row.value,'$.media_scope'),'SESSION')='SESSION'), links AS MATERIALIZED (SELECT json_extract(row.value,'$.lesson_id') lesson_id,json_extract(row.value,'$.asset_id') asset_id FROM setup_head_components h JOIN setup_components c USING(component_id),json_each(c.rows_json) row WHERE h.head_id=NEW.head_id AND h.table_name='lesson_media_links'), assets AS MATERIALIZED (SELECT json_extract(row.value,'$.asset_id') asset_id FROM setup_head_components h JOIN setup_components c USING(component_id),json_each(c.rows_json) row WHERE h.head_id=NEW.head_id AND h.table_name='lesson_media_assets' AND json_extract(row.value,'$.kind')='PDF') SELECT 1 FROM parents p WHERE (SELECT count(*) FROM links l JOIN assets a USING(asset_id) WHERE l.lesson_id=p.id)+(SELECT count(*) FROM lesson_note_entries n WHERE n.activity_key=p.activity_key AND n.session_key=p.session_key AND n.state='ACTIVE')>10)
 BEGIN SELECT RAISE(ABORT,'lesson_media_pdf_limit'); END;

DROP TRIGGER IF EXISTS lesson_media_accepted_pdf_limit_update;

CREATE TRIGGER lesson_media_accepted_pdf_limit_update BEFORE UPDATE ON setup_head_state
 WHEN EXISTS(WITH parents AS MATERIALIZED (SELECT json_extract(row.value,'$.lesson_id') id,json_extract(row.value,'$.activity_key') activity_key,json_extract(row.value,'$.session_key') session_key FROM setup_head_components h JOIN setup_components c USING(component_id),json_each(c.rows_json) row WHERE h.head_id=NEW.head_id AND h.table_name='lesson_media_lessons' AND json_extract(row.value,'$.state')='PUBLISHED' AND coalesce(json_extract(row.value,'$.media_scope'),'SESSION')='SESSION'), links AS MATERIALIZED (SELECT json_extract(row.value,'$.lesson_id') lesson_id,json_extract(row.value,'$.asset_id') asset_id FROM setup_head_components h JOIN setup_components c USING(component_id),json_each(c.rows_json) row WHERE h.head_id=NEW.head_id AND h.table_name='lesson_media_links'), assets AS MATERIALIZED (SELECT json_extract(row.value,'$.asset_id') asset_id FROM setup_head_components h JOIN setup_components c USING(component_id),json_each(c.rows_json) row WHERE h.head_id=NEW.head_id AND h.table_name='lesson_media_assets' AND json_extract(row.value,'$.kind')='PDF') SELECT 1 FROM parents p WHERE (SELECT count(*) FROM links l JOIN assets a USING(asset_id) WHERE l.lesson_id=p.id)+(SELECT count(*) FROM lesson_note_entries n WHERE n.activity_key=p.activity_key AND n.session_key=p.session_key AND n.state='ACTIVE')>10)
 BEGIN SELECT RAISE(ABORT,'lesson_media_pdf_limit'); END;
